            lastAuth = ex.getRequestHeaders().getFirst("Authorization");
            lastCType = ex.getRequestHeaders().getFirst("Content-Type");
            lastBody = new String(ex.getRequestBody().readAllBytes());
            int code = lastPath.startsWith("/models/") ? phase1
                     : lastPath.equals("/v1/chat/completions") ? phase2 : 404;
            byte[] b = "{}".getBytes();
            ex.sendResponseHeaders(code, b.length);
            ex.getResponseBody().write(b);
            ex.close();
